<?php
namespace App\Support;
use App\Models\{User,TimetableGovernanceState as State,TimetableGovernanceRole as Role,TimetableAllocationControl as Control,TimetablePlan as Plan};
use Illuminate\Support\Facades\{DB,Crypt};
class TimetableGovernance {
 public const ROLES=['inherit'=>'Existing timetable role','viewer'=>'Viewer','centre_manager'=>'Centre Manager (timetable)'];
 public static function ceo(User $u):bool {return $u->active&&$u->role==='ceo';}
 public static function event(User $u,string $event,string $type,string|int $key,int $version,array $data):void {DB::table('timetable_governance_events')->insert(['actor_id'=>$u->id,'event'=>$event,'subject_type'=>$type,'subject_key'=>(string)$key,'record_version'=>$version,'payload'=>Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function roleFields(Role $r):array {return $r->only(['user_id','role','restricted','ceo_locked','version','changed_by']);}
 public static function roleIntact(Role $r,User $u):bool {try{$h=$r->history;$last=$h?end($h):null;return $last&&$last['after']===self::roleFields($r)&&$last['staff_role']===$u->role;}catch(\Throwable){return false;}}
 public static function hasRole(User $u):bool {
  if(!CentrePlanning::staff($u)){return false;}if(self::ceo($u)){return true;}$r=Role::find($u->id);if($r){if(!self::roleIntact($r,$u)||$r->role==='viewer'){return false;}if($r->role==='centre_manager'){return true;}}
  // Existing individually checked centre-planner grants retain their timetable remit.
  return CentrePlanning::legacyRole($u);
 }
 public static function manager(User $u):bool {return self::hasRole($u);}
 public static function stateFields(State $s):array {return $s->only(['id','revision','editing_paused']);}
 public static function stateIntact(State $s):bool {try{if(!$s->details){return $s->id===1&&$s->revision===1&&!$s->editing_paused&&!DB::table('timetable_governance_events')->exists();}return $s->details['fields']===self::stateFields($s);}catch(\Throwable){return false;}}
 public static function canEdit(User $u):bool {if(self::ceo($u)){return true;}if(!self::hasRole($u)){return false;}$r=Role::find($u->id);if($r&&$r->restricted){return false;}$s=State::find(1);return $s&&self::stateIntact($s)&&!$s->editing_paused;}
 private static function actor(User $actor,int $auth):User {$u=User::whereKey($actor->id)->lockForUpdate()->firstOrFail();State::whereKey(1)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->auth_version===$auth&&self::canEdit($u)&&self::manager($u),403);return $u;}
 private static function state(int $revision):State {$s=State::whereKey(1)->lockForUpdate()->firstOrFail();if(!self::stateIntact($s)||$s->revision!==$revision){CentrePlanning::fail('Timetable controls changed; reload before deciding.');}return $s;}
 private static function bump(State $s,User $u,string $action,string $note):void {$s->revision++;$s->details=['fields'=>self::stateFields($s),'by'=>$u->id,'action'=>$action,'at'=>now()->toIso8601String(),'note'=>$note];$s->save();}
 public static function role(User $actor,int $auth,User $target,int $version,int $revision,string $role,bool $restricted,bool $ceoLocked,string $note):void {
  DB::transaction(function()use($actor,$auth,$target,$version,$revision,$role,$restricted,$ceoLocked,$note):void {User::whereIn('id',[$actor->id,$target->id])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);$s=self::state($revision);$t=User::findOrFail($target->id);$r=Role::whereKey($t->id)->lockForUpdate()->first();if(!CentrePlanning::staff($t)||self::ceo($t)||!isset(self::ROLES[$role])||($r?->version??0)!==$version||!filled($note)||mb_strlen($note)>2000){CentrePlanning::fail('Choose current eligible staff and an exact timetable role decision; CEO authority cannot be restricted here.');}if(!self::ceo($u)&&(($r?->ceo_locked??false)||$ceoLocked)){CentrePlanning::fail('Only the CEO can change a CEO-protected timetable decision.');}if($r&&!self::roleIntact($r,$t)){CentrePlanning::fail('Role proof needs recovery/review, not silent replacement.');}$before=$r?self::roleFields($r):null;$r??=new Role(['user_id'=>$t->id,'version'=>0]);$r->version++;$r->role=$role;$r->restricted=$restricted;$r->ceo_locked=$ceoLocked;$r->changed_by=$u->id;$h=$r->history??[];$h[]=['before'=>$before,'after'=>self::roleFields($r),'staff_role'=>$t->role,'by'=>$u->id,'note'=>$note,'at'=>now()->toIso8601String()];$r->history=$h;$r->save();self::bump($s,$u,'role',$note);self::event($u,'role_changed','user',$t->id,$r->version,['before'=>$before,'after'=>self::roleFields($r),'note'=>$note,'portal_role_changed'=>false]);},3);
 }
 public static function pause(User $actor,int $auth,int $revision,bool $paused,string $note):void {DB::transaction(function()use($actor,$auth,$revision,$paused,$note):void {$u=User::whereKey($actor->id)->lockForUpdate()->firstOrFail();abort_unless(self::ceo($u)&&$u->auth_version===$auth,403);$s=self::state($revision);if(!filled($note)||mb_strlen($note)>2000){CentrePlanning::fail('Record a safe reason for the CEO decision.');}$before=self::stateFields($s);$s->editing_paused=$paused;self::bump($s,$u,'ceo_pause',$note);self::event($u,'ceo_editing_control','state',1,$s->revision,['before'=>$before,'after'=>self::stateFields($s),'note'=>$note]);},3);}
 public static function allocationFields(Control $c):array {return $c->only(['plan_id','version','restricted','ceo_locked','changed_by']);}
 public static function allocationIntact(Control $c):bool {try{return $c->details&&$c->details['after']===self::allocationFields($c);}catch(\Throwable){return false;}}
 public static function guardPlan(User $u,Plan $p):void {
  if(self::ceo($u)){return;}$c=Control::whereKey($p->id)->lockForUpdate()->first();if($c&&(!self::allocationIntact($c)||$c->restricted||$c->ceo_locked)){CentrePlanning::fail('This planning allocation is protected; ask a permitted manager/CEO to review its control.');}
 }
 public static function allocation(User $actor,int $auth,Plan $record,int $version,int $revision,bool $restricted,bool $ceoLocked,string $note):void {DB::transaction(function()use($actor,$auth,$record,$version,$revision,$restricted,$ceoLocked,$note):void {$u=self::actor($actor,$auth);$s=self::state($revision);$p=Plan::whereKey($record->id)->lockForUpdate()->firstOrFail();$c=Control::whereKey($p->id)->lockForUpdate()->first();if(!CentrePlanning::intact($p)||($c?->version??0)!==$version||!filled($note)||mb_strlen($note)>2000){CentrePlanning::fail('Reload the exact intact allocation control.');}if(!self::ceo($u)&&(($c?->ceo_locked??false)||$ceoLocked)){CentrePlanning::fail('Only CEO can override a CEO-protected allocation.');}if($c&&!self::allocationIntact($c)){CentrePlanning::fail('Allocation-control proof needs recovery.');}$before=$c?self::allocationFields($c):null;$c??=new Control(['plan_id'=>$p->id,'version'=>0]);$c->version++;$c->restricted=$restricted;$c->ceo_locked=$ceoLocked;$c->changed_by=$u->id;$c->details=['before'=>$before,'after'=>self::allocationFields($c),'by'=>$u->id,'note'=>$note,'at'=>now()->toIso8601String()];$c->save();self::bump($s,$u,'allocation',$note);self::event($u,'allocation_control','plan',$p->id,$c->version,['before'=>$before,'after'=>self::allocationFields($c),'note'=>$note]);},3);}
 public static function legacyChange(User $actor,User $target):void {abort_if(self::ceo($target),403);abort_unless(self::canEdit($actor),403);$r=Role::find($target->id);if($r){CentrePlanning::fail('Use timetable Roles & control for a person with a reviewed role decision.');}}
 public static function legacyRecorded(User $u,User $target):void {$s=State::whereKey(1)->lockForUpdate()->firstOrFail();if(!self::stateIntact($s)){CentrePlanning::fail('Governance proof needs recovery.');}self::bump($s,$u,'existing_grant','Existing checked planner grant updated');self::event($u,'existing_grant_changed','user',$target->id,$s->revision,['portal_role_changed'=>false]);}
 public static function label(User $u):string {if(self::ceo($u)){return 'CEO';}$r=Role::find($u->id);if($r&&!self::roleIntact($r,$u)){return 'Role source needs review';}if($r&&$r->role==='viewer'){return 'Viewer';}if(($r&&$r->role==='centre_manager')||CentrePlanning::legacyRole($u)){return $u->role==='admin'?'Admin':'Centre Manager (timetable)';}return 'Viewer';}

 public static function section(User $u):string {$s=\App\Models\TimetableStaffSection::find($u->id);if($s){try{if($s->details['fields']===$s->only(['user_id','section','version','changed_by'])&&in_array($s->section,['teaching','other'],true)){return $s->section;}}catch(\Throwable){}return 'review';}return in_array($u->role,['tutor','functional_skills_tutor'],true)?'teaching':'other';}
 public static function sectionLabel(User $u):string {return match(self::section($u)){'teaching'=>'Teaching tutors','other'=>'Other staff',default=>'Section needs review'};}
 public static function saveSection(User $actor,int $auth,User $target,int $version,int $revision,string $section,string $note):void {DB::transaction(function()use($actor,$auth,$target,$version,$revision,$section,$note):void {$u=self::actor($actor,$auth);$s=self::state($revision);$t=User::whereKey($target->id)->lockForUpdate()->firstOrFail();$r=\App\Models\TimetableStaffSection::whereKey($t->id)->lockForUpdate()->first();if(!CentrePlanning::staff($t)||!in_array($section,['teaching','other'],true)||($r?->version??0)!==$version||!filled($note)||mb_strlen($note)>2000||($r&&self::section($t)==='review')){CentrePlanning::fail('Reload a current staff section and record a reason.');}$before=$r?->only(['user_id','section','version','changed_by']);$r??=new \App\Models\TimetableStaffSection(['user_id'=>$t->id,'version'=>0]);$r->version++;$r->section=$section;$r->changed_by=$u->id;$r->details=['fields'=>$r->only(['user_id','section','version','changed_by']),'before'=>$before,'note'=>$note];$r->save();self::bump($s,$u,'section',$note);self::event($u,'staff_section_changed','user',$t->id,$r->version,['before'=>$before,'after'=>$r->details['fields'],'note'=>$note,'permissions_changed'=>false]);},3);}

}
